+          projectIndexRef.current = effIndex;
+          setRoleScope(effScope);
+          setProjectIndex(effIndex);
+        } else {
+          effScope = "global";
+          roleScopeRef.current = effScope;
+          setRoleScope(effScope);
+        }
+      }
+      const effKey = scopeKeyFor(effScope, effIndex);
