+  it("uses the google effort ladder for gemini models", () => {
+    const entry = buildOmpModelEntry("gc/gemini-3-pro-preview", {
+      vision: true,
+      reasoning: true,
+      thinkingFormat: "gemini-level",
+      contextWindow: 1048576,
