+  it("floors fractional limits to integers", () => {
+    const entry = buildOmpModelEntry("frac/model", { contextWindow: 200000.7, maxOutput: 64000.9 });
+    expect(entry.contextWindow).toBe(200000);
+    expect(entry.maxTokens).toBe(64000);
